#include <stdio.h>

int main(void)
{
    double total = 0.0;
    for (int i = 0; i < 3; i++) {
        int quantity = 0;
        double price = 0.0;
        if (scanf("%d %lf", &quantity, &price) != 2) {
            break;
        }
        double line = quantity * price;
        total += line;
        printf("%3d x %6.2f = %6.2f\n", quantity, price, line);
    }
    printf("Total: %14.2f\n", total);
    return 0;
}
